public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0) {
        return "cannot be travelled";
    }
    if (start == null || start.length == 0 || end == null || end.length == 0 || paths == null) {
        return "cannot be travelled";
    }
    int startIdx = start[0];
    int endIdx = end[0];
    if (startIdx < 0 || startIdx >= n || endIdx < 0 || endIdx >= n) {
        return "cannot be travelled";
    }
    List<List<Integer>> adj = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] p : paths) {
        if (p == null || p.length < 2) {
            continue;
        }
        int a = p[0];
        int b = p[1];
        if (a < 0 || a >= n || b < 0 || b >= n) {
            continue;
        }
        adj.get(a).add(b);
        adj.get(b).add(a);
    }
    if (startIdx == endIdx) {
        return "can be travelled";
    }
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new ArrayDeque<>();
    queue.add(startIdx);
    visited[startIdx] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        for (int neighbor : adj.get(cur)) {
            if (!visited[neighbor]) {
                if (neighbor == endIdx) {
                    return "can be travelled";
                }
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

