    int curr = 1;
    for (int i = 0; i < n; i++) {
        result.add(curr);
        if ((long) curr * 10 <= n) {
            curr *= 10;
        } else {
            while (curr % 10 == 9 || curr + 1 > n) {
                curr /= 10;
            }
            curr += 1;
        }
    }
    return result;
}

